SELECT ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tenant_memberships' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_unicode_ci')=1
AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tenant_memberships')=8
AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tenant_memberships' AND COLUMN_NAME IN ('id','tenant_id','tenant_kind','user_id','role_id','status','created_at','updated_at'))=8
AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tenant_memberships' AND CONSTRAINT_NAME IN ('uq_membership_user','uq_membership_owner','uq_membership_actor','fk_membership_tenant','fk_membership_role','fk_membership_user'))=6) AS satisfied
